-- Nội dung soạn sẵn cho từng điểm chạm (email / Zalo / LinkedIn / kịch bản gọi) và thông tin người gửi.
-- Biến: {ten} tên người nhận, {cong_ty} công ty khách, {playlist} link playlist theo nhóm khách,
--       {nguoi_gui}, {chuc_danh}, {cong_ty_ban}, {sdt}, {chu_ky}. Sửa được ở Cài đặt.

insert into public.settings (key, value) values
  ('sender', $json${"name": "", "title": "Account Manager", "company": "Bigfish Agency", "phone": ""}$json$::jsonb),
  ('message_templates', $json$[
    {"step": 1, "channel": "linkedin", "segment": "all", "title": "Lời mời kết nối LinkedIn (≤ 300 ký tự)",
     "body": "Chào {ten}, mình là {nguoi_gui} ở {cong_ty_ban}. Mình làm về nhạc bản quyền cho đài truyền hình, MCN và production house tại Việt Nam và rất thích nội dung của {cong_ty}. Rất vui được kết nối!"},

    {"step": 2, "channel": "email", "segment": "broadcaster", "title": "Email mở lời — đài truyền hình",
     "subject": "Nhạc bản quyền cho chương trình của {cong_ty}",
     "body": "Chào {ten},\n\nEm là {nguoi_gui} từ {cong_ty_ban}. Bên em đang hỗ trợ các đài và đơn vị sản xuất tại Việt Nam dùng kho nhạc Epidemic Sound (hơn 50.000 bài nhạc, 200.000 hiệu ứng âm thanh) cho bản tin, chương trình giải trí và nội dung đăng YouTube / mạng xã hội — một giấy phép, hạn chế tối đa rủi ro bị claim bản quyền.\n\nEm gửi anh/chị playlist mẫu để tham khảo: {playlist}\n\nAnh/chị có tiện trao đổi 15 phút trong tuần này để em hiểu nhu cầu nhạc của {cong_ty} không ạ?\n\nTrân trọng,\n{chu_ky}"},
    {"step": 2, "channel": "email", "segment": "mcn", "title": "Email mở lời — MCN / mạng creator",
     "subject": "Nhạc an toàn bản quyền cho creator của {cong_ty}",
     "body": "Chào {ten},\n\nEm là {nguoi_gui} từ {cong_ty_ban}. Bên em giúp các MCN cấp nhạc Epidemic Sound cho creator trong mạng lưới: hơn 50.000 bài nhạc và 200.000 hiệu ứng, dùng cho YouTube, TikTok, Facebook mà không lo bị claim khi kênh được kết nối giấy phép.\n\nPlaylist mẫu cho nội dung creator: {playlist}\n\nAnh/chị có 15 phút trong tuần này để em trình bày cách các MCN đang triển khai không ạ?\n\nTrân trọng,\n{chu_ky}"},
    {"step": 2, "channel": "email", "segment": "agency", "title": "Email mở lời — production house / agency",
     "subject": "Chọn nhạc nhanh hơn cho dự án của {cong_ty}",
     "body": "Chào {ten},\n\nEm là {nguoi_gui} từ {cong_ty_ban}. Các production house thường mất nhiều giờ tìm nhạc và xin quyền cho từng TVC, video doanh nghiệp. Với Epidemic Sound, đội dựng chọn nhạc trong kho hơn 50.000 bài, tải cả stems (trống, bass, giai điệu) để dựng, và dùng cho khách hàng trong phạm vi giấy phép.\n\nPlaylist mẫu cho TVC / corporate: {playlist}\n\nAnh/chị có tiện trao đổi 15 phút trong tuần này không ạ?\n\nTrân trọng,\n{chu_ky}"},
    {"step": 2, "channel": "email", "segment": "film", "title": "Email mở lời — hãng phim / hậu kỳ",
     "subject": "Nhạc nền và hiệu ứng cho dự án phim của {cong_ty}",
     "body": "Chào {ten},\n\nEm là {nguoi_gui} từ {cong_ty_ban}. Bên em hỗ trợ các đơn vị phim và hậu kỳ dùng Epidemic Sound cho trailer, teaser, nội dung quảng bá và phim tài liệu: hơn 50.000 bài nhạc kèm stems và 200.000 hiệu ứng âm thanh.\n\nPlaylist mẫu trailer / điện ảnh: {playlist}\n\nAnh/chị có 15 phút trong tuần này để trao đổi về các dự án sắp tới không ạ?\n\nTrân trọng,\n{chu_ky}"},
    {"step": 2, "channel": "email", "segment": "brand", "title": "Email mở lời — nhãn hàng",
     "subject": "Âm nhạc nhất quán cho nội dung thương hiệu {cong_ty}",
     "body": "Chào {ten},\n\nEm là {nguoi_gui} từ {cong_ty_ban}. Đội marketing của nhiều thương hiệu dùng Epidemic Sound để có nhạc bản quyền cho social, quảng cáo và sự kiện — một giấy phép cho cả đội và agency, giữ âm thanh thương hiệu nhất quán.\n\nPlaylist mẫu: {playlist}\n\nAnh/chị có 15 phút trong tuần này để em giới thiệu nhanh không ạ?\n\nTrân trọng,\n{chu_ky}"},

    {"step": 3, "channel": "call", "segment": "all", "title": "Kịch bản gọi lần 1",
     "body": "• Mở lời (10 giây): \"Chào anh/chị {ten}, em {nguoi_gui} bên {cong_ty_ban}, em vừa gửi email về nhạc bản quyền cho {cong_ty}. Anh/chị cho em xin 2 phút được không ạ?\"\n• Hỏi 1 câu: \"Hiện bên mình chọn nhạc cho video / chương trình thế nào ạ? Có hay gặp claim bản quyền không?\"\n• Chốt: hẹn 15 phút trao đổi, đưa 2 khung giờ.\n• Không nghe máy → gửi Zalo ngay trong ngày (bước 4)."},
    {"step": 4, "channel": "zalo", "segment": "all", "title": "Zalo: vài bản nhạc mẫu",
     "body": "Chào anh/chị {ten}, em {nguoi_gui} bên {cong_ty_ban} ạ. Em vừa gửi email, em gửi nhanh vài bài nhạc hợp với nội dung của {cong_ty} để anh/chị nghe thử: {playlist}\nNếu thấy hợp, em chọn thêm theo dự án cụ thể của bên mình nhé!"},
    {"step": 5, "channel": "email", "segment": "all", "title": "Email theo sau: khách hàng tương tự",
     "subject": "Re: {cong_ty} — cách các đơn vị cùng ngành đang dùng nhạc",
     "body": "Chào {ten},\n\nEm gửi thêm thông tin ngắn: năm nay một số đài truyền hình và đơn vị sản xuất lớn tại Việt Nam đã chuyển sang dùng Epidemic Sound để có một nguồn nhạc bản quyền chung cho cả đội — em có thể chia sẻ cụ thể hơn khi mình trao đổi.\n\nNếu anh/chị cho em biết loại nội dung bên mình làm nhiều nhất, em sẽ gửi playlist chọn riêng.\n\nTrân trọng,\n{chu_ky}"},
    {"step": 6, "channel": "call", "segment": "all", "title": "Kịch bản gọi lần 2 (đổi khung giờ)",
     "body": "• Gọi khác giờ lần 1 (sáng sớm 8:30–9:30 hoặc chiều 16:30–17:30).\n• \"Em gọi lại về playlist em gửi hôm trước, anh/chị đã nghe thử chưa ạ?\"\n• Nếu bận: \"Khi nào em gọi lại tiện nhất ạ?\" → ghi giờ vào Việc tiếp theo."},
    {"step": 7, "channel": "linkedin", "segment": "all", "title": "Tin nhắn LinkedIn",
     "body": "Cảm ơn {ten} đã kết nối! Mình có gửi email về nhạc bản quyền cho {cong_ty}. Nếu tiện, mình gửi playlist mẫu ở đây luôn: {playlist} — rất mong nghe góp ý của bạn."},
    {"step": 8, "channel": "email", "segment": "all", "title": "Email giá trị: 3 lỗi bản quyền nhạc hay gặp",
     "subject": "3 lỗi bản quyền nhạc khiến video bị claim",
     "body": "Chào {ten},\n\nEm tổng hợp nhanh 3 lỗi hay gặp khi đăng video:\n1. Dùng nhạc “free” trên mạng nhưng không có giấy phép thương mại.\n2. Giấy phép theo từng bài, hết hạn hoặc không bao gồm nền tảng mới (TikTok, Reels).\n3. Kênh chưa được kết nối giấy phép nên vẫn bị Content ID claim.\n\nEpidemic Sound giải quyết cả 3 bằng một giấy phép cho cả đội. Anh/chị muốn em kiểm tra nhanh trường hợp của {cong_ty} không ạ?\n\nTrân trọng,\n{chu_ky}"},
    {"step": 9, "channel": "zalo", "segment": "all", "title": "Zalo: playlist theo dự án",
     "body": "Anh/chị {ten} ơi, em thấy {cong_ty} vừa có [tên dự án / chương trình] — em chọn thử một playlist hợp không khí dự án này: {playlist}\nAnh/chị nghe thử 1–2 bài xem có hợp không nhé!"},
    {"step": 10, "channel": "call", "segment": "all", "title": "Kịch bản gọi lần 3",
     "body": "• \"Em hỏi thẳng để không làm mất thời gian của anh/chị: quý tới bên mình có kế hoạch dùng nhạc cho dự án nào không ạ?\"\n• Có → hẹn demo 15 phút. Chưa → hỏi tháng lên ngân sách, ghi vào Việc tiếp theo."},
    {"step": 11, "channel": "email", "segment": "all", "title": "Email mời demo 15 phút",
     "subject": "15 phút demo Epidemic Sound cho {cong_ty}?",
     "body": "Chào {ten},\n\nEm xin 15 phút để demo trực tiếp trên nội dung thật của {cong_ty}: tìm nhạc theo mood, tải stems, và cách kết nối kênh để tránh claim.\n\nAnh/chị chọn giúp em một khung giờ:\n• [Thứ …, …h]\n• [Thứ …, …h]\n\nHoặc anh/chị gợi ý giờ khác cũng được ạ.\n\nTrân trọng,\n{chu_ky}"},
    {"step": 13, "channel": "email", "segment": "all", "title": "Email hẹn buổi tìm hiểu nhu cầu",
     "subject": "Hẹn 20 phút trao đổi nhu cầu nhạc của {cong_ty}",
     "body": "Chào {ten},\n\nCảm ơn anh/chị đã phản hồi! Em xin 20 phút để hiểu cách {cong_ty} đang dùng nhạc (loại nội dung, số lượng video, nền tảng phát) để đề xuất gói phù hợp.\n\nAnh/chị tiện khung nào ạ:\n• [Thứ …, …h]\n• [Thứ …, …h]\n\nTrân trọng,\n{chu_ky}"},
    {"step": 15, "channel": "email", "segment": "all", "title": "Email gửi đề xuất",
     "subject": "Đề xuất Epidemic Sound cho {cong_ty}",
     "body": "Chào {ten},\n\nEm gửi anh/chị đề xuất theo buổi trao đổi vừa rồi (đính kèm). Tóm tắt:\n• Phạm vi: [số người dùng / kênh / nền tảng]\n• Chi phí: [… USD/năm]\n• Bắt đầu: [ngày]\n\nAnh/chị xem giúp em và cho em biết cần làm rõ điểm nào nhé. Em sẽ gọi lại vào [ngày] để trao đổi tiếp.\n\nTrân trọng,\n{chu_ky}"},
    {"step": 16, "channel": "call", "segment": "all", "title": "Gọi theo dõi đề xuất",
     "body": "• \"Anh/chị đã xem đề xuất em gửi chưa ạ? Có điểm nào cần điều chỉnh không?\"\n• Hỏi: ai cần duyệt, khi nào duyệt, có vướng ngân sách không.\n• Ghi rõ ngày duyệt vào Việc tiếp theo."},
    {"step": 90, "channel": "email", "segment": "all", "title": "Điểm chạm nuôi dưỡng (giá trị, không chào bán)",
     "subject": "Playlist mới cho {cong_ty} tháng này",
     "body": "Chào {ten},\n\nEm gửi anh/chị playlist mới tuyển chọn tháng này, hợp với nội dung bên mình: {playlist}\n\nKhông cần trả lời đâu ạ — khi nào {cong_ty} cần nhạc cho dự án mới, anh/chị nhắn em nhé.\n\nTrân trọng,\n{chu_ky}"},
    {"step": 12, "channel": "email", "segment": "all", "title": "Email cuối chặng (người thứ 2 / tạm dừng)",
     "subject": "Có nên tiếp tục không ạ?",
     "body": "Chào {ten},\n\nEm đã liên hệ vài lần mà chưa đúng thời điểm, nên em xin phép tạm dừng để không làm phiền anh/chị.\n\nNếu nhu cầu nhạc bên mình do người khác phụ trách, anh/chị giới thiệu giúp em được không ạ? Còn nếu để sau, em sẽ quay lại vào dịp khác.\n\nCảm ơn anh/chị nhiều!\n{chu_ky}"}
  ]$json$::jsonb)
on conflict (key) do nothing;
